import numpy as np

def problem(x: np.ndarray) -> float:
    """Combines a quadratic bowl with sinusoidal modulation and pairwise interactions to achieve target ELA features."""
    return (
        0.05 * np.sum(x**2)  # Quadratic bowl
        + 0.02 * np.sum(np.sin(2 * x))  # Sinusoidal modulation for ruggedness
        + 0.01 * np.sum(x * np.roll(x, 1))  # Pairwise interactions
        + 0.005 * np.sum(x**3) #Add a Skewness  element
        + 0.0005 * np.sum(x**4) #Add further kurtosis/non-gaussian element
    )
